@push('scripts')<script>(function(){var modal=document.getElementById('spend-upload-modal'),key=document.getElementById('upload-account-key'),input=document.getElementById('upload-file'),drop=document.getElementById('upload-drop'),paste=document.getElementById('upload-paste-btn'),name=document.getElementById('upload-file-name');document.addEventListener('click',function(e){var b=e.target.closest('.js-upload-open');if(!b)return;key.value=b.dataset.key;input.value='';name.textContent='';});function show(){name.textContent=input.files.length?input.files[0].name:'';}input.addEventListener('change',show);drop.addEventListener('click',function(e){if(e.target.closest&&e.target.closest('#upload-paste-btn'))return;if(e.target===input)return;e.preventDefault();input.click();});paste.addEventListener('click',function(e){e.preventDefault();e.stopPropagation();drop.focus();});['dragenter','dragover'].forEach(function(x){drop.addEventListener(x,function(e){e.preventDefault();drop.classList.add('drag');});});['dragleave','drop'].forEach(function(x){drop.addEventListener(x,function(e){e.preventDefault();drop.classList.remove('drag');});});drop.addEventListener('drop',function(e){if(e.dataTransfer.files.length){input.files=e.dataTransfer.files;show();}});document.addEventListener('paste',function(e){if(!modal.classList.contains('in'))return;var items=e.clipboardData&&e.clipboardData.items;for(var i=0;items&&i<items.length;i++)if(items[i].type.indexOf('image/')===0){var dt=new DataTransfer();dt.items.add(items[i].getAsFile());input.files=dt.files;show();break;}});})();</script>@endpush
